//! Local (p-adic) Galois groups of a polynomial `f` over `ℚ_p` — the general-degree
//! namer (Module 9 / `pAdicGaloisGroup`).
//!
//! `Gal(f/ℚ_p)` is the decomposition group, a transitive subgroup of `S_n` (for `f`
//! irreducible). This module provides:
//!
//! - **Unramified primes (`p ∤ disc f`), any degree — exact and complete.** The local
//!   Galois group is **cyclic**, generated by the Frobenius, whose cycle type on the
//!   `n` roots is the multiset of factor degrees of `f mod p`. Hence
//!   `|Gal(f/ℚ_p)| = lcm` of those degrees, and the group is the cyclic group
//!   generated by that permutation. ([`unramified_local_galois_group`].)
//! - **Transitive-group data and orbit signatures** for small degrees, plus the
//!   `ℚ_p`-parity (`Gal ⊆ A_n ⟺ disc f` a square in `ℚ_p`), giving a **sound
//!   candidate set** at ramified primes ([`local_galois_candidates`]).
//!
//! The fully general *ramified* namer (separating e.g. `C₄`/`D₄` or `C₅`/`D₅` in all
//! ramification types) needs separable relative resolvents + Tschirnhaus transforms
//! and the mixed `ℚ_q`-tower — the CHIMP `pAdicGaloisGroup` machinery. The validated
//! degree-4 special case lives in `rustmath_numberfields::panayi`.
//!
//! Specification: MAGMA Handbook ch. 23 §23.8.1 (`Factorization` over F_p) for the
//! reduction, and the p-adic Galois group chapter (`GaloisGroup` over `Q_p`) for the local
//! groups. Every entry works on the primitive part `g` of the trimmed `f`: `f` and `g` have
//! the same roots, and `g mod p` is a nonzero binary form. The prime is checked first
//! ([`fp_factor::check_modulus`]): a composite `p`, `p < 2` or `p > fp_factor::MAX_P` panics.

use crate::ksubset_orbits::orbit_lengths_on_ksubsets;
use crate::transitive24::{cycle_type, is_odd_type, perm_from_cycles, Perm};
use rustmath_integers::Integer;
use rustmath_polynomials::{fp_factor, zx};

/// A named transitive subgroup of `S_n` (generators on the first `n` points).
#[derive(Debug, Clone)]
pub struct TransitiveSubgroup {
    pub label: &'static str, // e.g. "5T2"
    pub name: &'static str,  // e.g. "D5"
    pub order: usize,
    pub gens: Vec<Perm>,
}

fn pc(cycles: &[&[u8]]) -> Perm {
    perm_from_cycles(&cycles.iter().map(|c| c.to_vec()).collect::<Vec<_>>())
}

/// The transitive subgroups of `S_n` (with generators), for the degrees we tabulate.
pub fn transitive_groups(n: usize) -> Vec<TransitiveSubgroup> {
    match n {
        4 => vec![
            TransitiveSubgroup { label: "4T1", name: "C4", order: 4, gens: vec![pc(&[&[1, 2, 3, 4]])] },
            TransitiveSubgroup {
                label: "4T2", name: "V4", order: 4,
                gens: vec![pc(&[&[1, 2], &[3, 4]]), pc(&[&[1, 3], &[2, 4]])],
            },
            TransitiveSubgroup {
                label: "4T3", name: "D4", order: 8,
                gens: vec![pc(&[&[1, 2, 3, 4]]), pc(&[&[1, 3]])],
            },
            TransitiveSubgroup {
                label: "4T4", name: "A4", order: 12,
                gens: vec![pc(&[&[1, 2, 3]]), pc(&[&[2, 3, 4]])],
            },
            TransitiveSubgroup {
                label: "4T5", name: "S4", order: 24,
                gens: vec![pc(&[&[1, 2, 3, 4]]), pc(&[&[1, 2]])],
            },
        ],
        5 => vec![
            TransitiveSubgroup { label: "5T1", name: "C5", order: 5, gens: vec![pc(&[&[1, 2, 3, 4, 5]])] },
            TransitiveSubgroup {
                label: "5T2", name: "D5", order: 10,
                gens: vec![pc(&[&[1, 2, 3, 4, 5]]), pc(&[&[2, 5], &[3, 4]])],
            },
            TransitiveSubgroup {
                label: "5T3", name: "F20", order: 20,
                gens: vec![pc(&[&[1, 2, 3, 4, 5]]), pc(&[&[2, 3, 5, 4]])],
            },
            TransitiveSubgroup {
                label: "5T4", name: "A5", order: 60,
                gens: vec![pc(&[&[1, 2, 3, 4, 5]]), pc(&[&[3, 4, 5]])],
            },
            TransitiveSubgroup {
                label: "5T5", name: "S5", order: 120,
                gens: vec![pc(&[&[1, 2, 3, 4, 5]]), pc(&[&[1, 2]])],
            },
        ],
        _ => Vec::new(),
    }
}

/// The orbit-length signature of a group: sorted orbit lengths on `k`-subsets for
/// `k = 1 .. ⌊n/2⌋`.
pub fn orbit_signature(gens: &[Perm], n: usize) -> Vec<Vec<usize>> {
    (1..=n / 2).map(|k| orbit_lengths_on_ksubsets(gens, n, k)).collect()
}

/// Is the group `⟨gens⟩ ⊆ A_n` (all generators even permutations)?
pub fn group_in_alternating(gens: &[Perm]) -> bool {
    gens.iter().all(|g| !is_odd_type(&cycle_type(g)))
}

fn lcm_usize(a: usize, b: usize) -> usize {
    if a == 0 || b == 0 {
        return 0;
    }
    let (mut x, mut y) = (a, b);
    while y != 0 {
        let t = x % y;
        x = y;
        y = t;
    }
    a / x * b
}

/// The local Galois group at an **unramified** prime (any degree): it is cyclic,
/// generated by the Frobenius, whose cycle type on the roots is the multiset of the
/// factor degrees of `g mod p` (`g` the primitive part of `f`), plus one fixed point when
/// `p` divides the leading coefficient of `g`. [`unramified_local_galois_group`] returns
/// `None` if `p` divides the discriminant of the primitive part of `f` (ramified, or an
/// index divisor; not handled here).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct UnramifiedLocalGalois {
    /// Frobenius cycle type = factor degrees of `g mod p`, plus a `1` for the root at
    /// infinity when `p | lc(g)` (sorted; `g` the primitive part of `f`).
    pub frobenius_cycle_type: Vec<usize>,
    /// `|Gal(f/ℚ_p)| = lcm` of the cycle lengths (order of Frobenius).
    pub order: usize,
    /// Whether `f` is irreducible over `ℚ_p` (Frobenius is an `n`-cycle).
    pub transitive: bool,
}

/// The primitive part of the trimmed `f` (the sign is kept).
fn primitive(f: &[Integer]) -> Vec<Integer> {
    zx::primitive_part(&zx::trim(f))
}

/// Panic `"{who}: {why}"` unless `p` is a prime `<= fp_factor::MAX_P`.
fn check_prime(p: i64, who: &str) {
    if let Err(why) = fp_factor::check_modulus(p) {
        panic!("{who}: {why}");
    }
}

/// Local Galois group at a prime `p` that does not divide `disc(g)`, where `g` is the
/// primitive part of `f` (`f` and `g` have the same roots). Returns `None` iff
/// `p | disc(g)` (ramified, or an index divisor; not handled here).
///
/// Why it is exact. Let `n = deg g` and `G(X, Y) = Σ a_i X^i Y^(n-i)`. As `p ∤ content(g)`,
/// `G mod p` is a nonzero binary form of degree `n`. For `n >= 2` the discriminant of `G`
/// equals `disc(g)` up to sign and commutes with reduction, so `p ∤ disc(g)` gives `n`
/// distinct roots of `G mod p` on `P^1`; the root at infinity has multiplicity
/// `n - deg(g mod p) <= 1`. For `n = 1`, `disc(g) = 1` and `deg(g mod p) ∈ {0, 1}`. So
/// `V(G)` is finite étale over `Z_p`, the splitting field is unramified, and Frobenius has
/// the cycle type of the closed points of `G mod p`: the factor degrees of `g mod p`, plus
/// a fixed point (a root in `Q_p`, by Hensel on the reversed polynomial) when
/// `deg(g mod p) = n - 1`.
///
/// # Panics
///
/// `p` is not a prime `<= fp_factor::MAX_P` ([`fp_factor::check_modulus`]); `f` has degree
/// `< 1` after trimming.
pub fn unramified_local_galois_group(f: &[Integer], p: i64) -> Option<UnramifiedLocalGalois> {
    const WHO: &str = "pgalois::unramified_local_galois_group";
    let g = primitive(f);
    let n = zx::degree(&g);
    if n < 1 {
        panic!("{WHO}: f must have degree >= 1");
    }
    check_prime(p, WHO);
    let disc = rustmath_polynomials::disc::discriminant(&g);
    if (disc % Integer::from(p)).is_zero() {
        return None; // p | disc(g)
    }
    // g mod p in [0, p), trimmed; nonzero since p ∤ content(g).
    let pz = Integer::from(p);
    let gbar: Vec<i64> = fp_factor::trim(
        &g.iter()
            .map(|c| i64::try_from(&c.modulo(&pz)).expect("a residue mod an i64 p fits in i64"))
            .collect::<Vec<i64>>(),
    );
    let nbar = fp_factor::degree(&gbar);
    let mut degs: Vec<usize> = if nbar >= 1 {
        fp_factor::factor(&gbar, p)
            .iter()
            .map(|h| fp_factor::degree(h) as usize)
            .collect()
    } else {
        Vec::new()
    };
    if nbar == n - 1 {
        degs.push(1); // the root at infinity: p | lc(g)
    } else if nbar < n - 1 {
        unreachable!("pgalois: deg(g mod p) < deg g - 1 with p ∤ content(g)·disc(g)");
    }
    degs.sort_unstable();
    let order = degs.iter().fold(1usize, |a, &d| lcm_usize(a, d));
    Some(UnramifiedLocalGalois {
        transitive: degs.len() == 1 && degs[0] as i64 == n,
        order,
        frobenius_cycle_type: degs,
    })
}

/// A **sound** candidate set for `Gal(f/ℚ_p)` among the tabulated transitive groups of
/// degree `n = deg f`:
/// - at an unramified prime, the unique cyclic group of the Frobenius order;
/// - at a ramified prime, every tabulated group whose `ℚ_p`-parity matches
///   (`Gal ⊆ A_n ⟺ disc f` a square in `ℚ_p`). The true group is always included.
///
/// Returns `(labels, exact)` where `exact` is `true` when the set is a singleton
/// (the group is determined). `f` is replaced by its primitive part (same roots). A
/// constant `f`, or a degree with no table, gives `([], false)`: no claim.
///
/// # Panics
///
/// `p` is not a prime `<= fp_factor::MAX_P` (checked first, also for degrees with no
/// table).
pub fn local_galois_candidates(f: &[Integer], p: i64) -> (Vec<&'static str>, bool) {
    check_prime(p, "pgalois::local_galois_candidates");
    let g = primitive(f);
    let n = zx::degree(&g);
    if n < 1 {
        return (Vec::new(), false);
    }
    let groups = transitive_groups(n as usize);
    if groups.is_empty() {
        return (Vec::new(), false);
    }
    // Unramified: cyclic of the Frobenius order — pick the matching tabulated group.
    if let Some(u) = unramified_local_galois_group(&g, p) {
        if u.transitive {
            let hits: Vec<&'static str> = groups
                .iter()
                .filter(|g| g.order == u.order && cyclic_label_matches(g, u.order))
                .map(|g| g.label)
                .collect();
            return (if hits.is_empty() { vec![] } else { hits }, true);
        }
        // f reducible mod p ⇒ intransitive cyclic group; not in the transitive table.
        return (Vec::new(), true);
    }
    // Ramified: narrow by the ℚ_p-parity of the discriminant. disc(f) = c^(2n-2) disc(g)
    // for f = c·g, and c^(2n-2) is a nonzero square, so disc(g) has the square class of
    // disc(f).
    let disc = rustmath_polynomials::disc::discriminant(&g);
    let dsq = is_padic_square(&disc, p);
    let cands: Vec<&'static str> = groups
        .iter()
        .filter(|g| group_in_alternating(&g.gens) == dsq)
        .map(|g| g.label)
        .collect();
    let exact = cands.len() == 1;
    (cands, exact)
}

fn cyclic_label_matches(g: &TransitiveSubgroup, order: usize) -> bool {
    // The cyclic transitive group C_n is "nT1" of order n.
    g.order == order && g.gens.len() == 1
}

/// Is the integer `d` a square in `ℚ_p`? (`v_p(d)` even and the unit part a square.)
///
/// # Panics
///
/// `p` is not a prime (`rustmath_integers::prime::is_prime_u64`, exact for every `i64`;
/// there is no upper limit, the arithmetic is on `Integer`).
pub fn is_padic_square(d: &Integer, p: i64) -> bool {
    if !(p >= 2 && rustmath_integers::prime::is_prime_u64(p as u64)) {
        panic!("pgalois::is_padic_square: p = {p} is not a prime");
    }
    if d.is_zero() {
        return true;
    }
    let pi = Integer::from(p);
    let v = d.abs().valuation(&pi);
    if v % 2 == 1 {
        return false;
    }
    let u = d.clone() / pi.pow(v);
    if p == 2 {
        let mut m = u % Integer::from(8);
        if m.signum() < 0 {
            m = m + Integer::from(8);
        }
        m == Integer::one()
    } else {
        let mut m = u % pi.clone();
        if m.signum() < 0 {
            m = m + pi.clone();
        }
        m.modpow(&Integer::from((p - 1) / 2), &pi).map(|r| r == Integer::one()).unwrap_or(false)
    }
}
